  if (fs.existsSync(target) && fs.readFileSync(target, "utf8") === sourceContent) {
    return false;
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, sourceContent, "utf8");
  return true;
}

function writeSplitRaw(source, target, sourceContent) {
  let changed = false;
  const sourceBuffer = Buffer.from(sourceContent, "utf8");
  const chunkCount = Math.ceil(sourceBuffer.length / rawChunkBytes);
  const manifest = [
    `# Split Codex raw rollout`,
    ``,
    `source: ${source}`,
    `original_bytes_utf8: ${sourceBuffer.length}`,
    `chunks: ${chunkCount}`,
    `chunk_pattern: ${path.basename(target)}.partNNN`,
    ``,
    `This raw rollout is split to keep each Git blob below GitHub's 100MB hard limit.`,
    `Concatenate the part files in numeric order to reconstruct the redacted JSONL content.`,
    ``,
  ].join("\n");

  fs.mkdirSync(path.dirname(target), { recursive: true });
  if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== manifest) {
    fs.writeFileSync(target, manifest, "utf8");
    changed = true;
  }

  for (let i = 0; i < chunkCount; i += 1) {
    const chunkPath = `${target}.part${String(i + 1).padStart(3, "0")}`;
    const chunk = sourceBuffer.subarray(i * rawChunkBytes, Math.min((i + 1) * rawChunkBytes, sourceBuffer.length));
    if (!fs.existsSync(chunkPath) || !fs.readFileSync(chunkPath).equals(chunk)) {
      fs.writeFileSync(chunkPath, chunk);
      changed = true;
    }
  }

